initJs:
function(container, apiUrl, tables) {
  const storeTable = tables.find(t => t.tableName === '店舗マスタ') || tables[1];
  const productTable = tables.find(t => t.tableName === '商品マスタ') || tables[2];
  const predictionTable = tables.find(t => t.tableName === '需要予測結果') || tables[8];
  const orderTable = tables.find(t => t.tableName === '発注データ') || tables[9];

  let currentProducts = [];
  let currentPredictions = [];
  let selectedProductId = null;

  // 店舗選択肢を初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    const stores = storeTable.records || [];
    stores.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        storeSelect.appendChild(option);
      }
    });
  }

  // 商品テーブル再描画
  function renderProducts(products, predictions) {
    const tbody = container.querySelector('#product-tbody');
    const table = container.querySelector('#product-table');
    const noStoreMessage = container.querySelector('#no-store-message');

    if (!products || products.length === 0) {
      table.classList.add('hidden');
      noStoreMessage.classList.remove('hidden');
      tbody.innerHTML = '';
      return;
    }

    noStoreMessage.classList.add('hidden');
    table.classList.remove('hidden');

    tbody.innerHTML = products.map(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID) || {};
      const currentStock = Math.floor(Math.random() * 100) + 10; // 模擬在庫データ

      return `
        <tr data-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-id="${product.商品ID}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${getCategoryName(product.商品カテゴリID)}</td>
          <td>${currentStock}</td>
          <td>${prediction.予測数量 || 0}</td>
          <td>${prediction.推奨発注数量 || 0}</td>
          <td>
            <div style="display: flex; align-items: center; gap: 4px;">
              <button class="adjust-btn" data-action="decrease" data-id="${product.商品ID}">-</button>
              <input type="number" class="quantity-input" data-id="${product.商品ID}" 
                     value="${prediction.推奨発注数量 || 0}" min="0">
              <button class="adjust-btn" data-action="increase" data-id="${product.商品ID}">+</button>
            </div>
          </td>
          <td>
            <textarea class="reason-input" data-id="${product.商品ID}" 
                      placeholder="発注理由"></textarea>
          </td>
          <td>
            <button class="action-btn secondary order-btn" data-id="${product.商品ID}">発注</button>
          </td>
        </tr>
      `;
    }).join('');

    updatePredictionSummary(products, predictions);
  }

  // カテゴリ名取得
  function getCategoryName(categoryId) {
    const categories = {
      '1': '食品',
      '2': '日用品', 
      '3': '衣料品',
      '4': '家電'
    };
    return categories[categoryId] || '未分類';
  }

  // 予測サマリー更新
  function updatePredictionSummary(products, predictions) {
    const predictionCount = predictions.length;
    const totalPrediction = predictions.reduce((sum, p) => sum + (p.予測数量 || 0), 0);
    const totalOrderAmount = predictions.reduce((sum, p) => {
      const product = products.find(pr => pr.商品ID === p.商品ID);
      return sum + ((p.推奨発注数量 || 0) * (product?.単価 || 0));
    }, 0);

    container.querySelector('#prediction-count').textContent = predictionCount;
    container.querySelector('#total-prediction').textContent = totalPrediction.toLocaleString();
    container.querySelector('#total-order-amount').textContent = `¥${totalOrderAmount.toLocaleString()}`;
  }

  // 店舗変更時の処理
  async function handleStoreChange() {
    const storeId = container.querySelector('#store-select').value;

    if (!storeId) {
      renderProducts([], []);
      return;
    }

    try {
      const products = await window.aivicApi.list(2); // 商品マスタ
      const predictions = await window.aivicApi.list(8); // 需要予測結果

      if (products && predictions) {
        const storeProducts = products.filter(p => p.有効フラグ);
        const storePredictions = predictions.filter(p => p.店舗ID === storeId);

        currentProducts = storeProducts;
        currentPredictions = storePredictions;

        applyFilters();
      }
    } catch (error) {
      console.error('データ取得エラー:', error);
    }
  }

  // フィルター適用
  function applyFilters() {
    let filteredProducts = [...currentProducts];
    let filteredPredictions = [...currentPredictions];

    // カテゴリフィルター
    const category = container.querySelector('#category-select').value;
    if (category) {
      const categoryMap = { '食品': '1', '日用品': '2', '衣料品': '3', '家電': '4' };
      const categoryId = categoryMap[category];
      if (categoryId) {
        filteredProducts = filteredProducts.filter(p => p.商品カテゴリID === categoryId);
      }
    }

    // 商品名検索
    const searchText = container.querySelector('#product-search').value.toLowerCase();
    if (searchText) {
      filteredProducts = filteredProducts.filter(p => 
        (p.商品名 || '').toLowerCase().includes(searchText) ||
        (p.商品コード || '').toLowerCase().includes(searchText)
      );
    }

    // 予測データも商品に合わせてフィルター
    const productIds = filteredProducts.map(p => p.商品ID);
    filteredPredictions = filteredPredictions.filter(p => productIds.includes(p.商品ID));

    renderProducts(filteredProducts, filteredPredictions);
  }

  // 検索処理
  function handleSearch() {
    const startDate = container.querySelector('#date-start').value;
    const endDate = container.querySelector('#date-end').value;

    // 日付バリデーション
    if (startDate && endDate && startDate > endDate) {
      alert('終了日は開始日以降の日付を入力してください');
      return;
    }

    applyFilters();
  }

  // 発注量調整
  function handleQuantityAdjust(productId, action) {
    const input = container.querySelector(`input.quantity-input[data-id="${productId}"]`);
    if (!input) return;

    let currentValue = parseInt(input.value) || 0;

    if (action === 'increase') {
      input.value = currentValue + 1;
    } else if (action === 'decrease' && currentValue > 0) {
      input.value = currentValue - 1;
    }
  }

  // 発注モーダル表示
  function showOrderModal(productId) {
    const product = currentProducts.find(p => p.商品ID === productId);
    if (!product) return;

    const modal = container.querySelector('#order-modal');
    const quantityInput = container.querySelector(`input.quantity-input[data-id="${productId}"]`);
    const reasonInput = container.querySelector(`textarea.reason-input[data-id="${productId}"]`);

    container.querySelector('#modal-product-name').textContent = product.商品名;
    container.querySelector('#modal-order-quantity').value = quantityInput?.value || 0;
    container.querySelector('#modal-order-reason').value = reasonInput?.value || '';

    // 納期予定日を設定（リードタイム考慮）
    const leadTime = product.リードタイム日数 || 3;
    const deliveryDate = new Date();
    deliveryDate.setDate(deliveryDate.getDate() + leadTime);
    container.querySelector('#modal-delivery-date').value = deliveryDate.toISOString().split('T')[0];

    selectedProductId = productId;
    modal.classList.remove('hidden');
  }

  // 発注実行
  async function executeOrder() {
    if (!selectedProductId) return;

    const quantity = parseInt(container.querySelector('#modal-order-quantity').value);
    const reason = container.querySelector('#modal-order-reason').value;
    const deliveryDate = container.querySelector('#modal-delivery-date').value;

    // バリデーション
    if (!quantity || quantity <= 0) {
      alert('発注量は正の数値を入力してください');
      return;
    }

    if (!reason.trim()) {
      alert('発注理由を入力してください');
      return;
    }

    const product = currentProducts.find(p => p.商品ID === selectedProductId);
    const prediction = currentPredictions.find(p => p.商品ID === selectedProductId);

    const orderData = {
      店舗ID: container.querySelector('#store-select').value,
      商品ID: selectedProductId,
      需要予測結果ID: prediction?.予測結果ID || null,
      発注日: new Date().toISOString(),
      納期予定日: new Date(deliveryDate).toISOString(),
      発注数量: quantity,
      予測数量: prediction?.予測数量 || 0,
      発注単価: product?.単価 || 0,
      発注金額: quantity * (product?.単価 || 0),
      発注方法: prediction?.推奨発注数量 === quantity ? 'AI推奨採用' : 'AI推奨修正',
      発注ステータス: '発注済',
      仕入先ID: product?.仕入先ID || '',
      発注理由: reason,
      自動発注フラグ: false,
      作成者ID: 'current-user-id',
      更新者ID: 'current-user-id'
    };

    try {
      const result = await window.aivicApi.save(9, orderData); // 発注データテーブル
      if (result) {
        alert('発注が完了しました');
        container.querySelector('#order-modal').classList.add('hidden');

        // 発注量と理由をクリア
        const quantityInput = container.querySelector(`input.quantity-input[data-id="${selectedProductId}"]`);
        const reasonInput = container.querySelector(`textarea.reason-input[data-id="${selectedProductId}"]`);
        if (quantityInput) quantityInput.value = 0;
        if (reasonInput) reasonInput.value = '';
      }
    } catch (error) {
      console.error('発注エラー:', error);
      alert('発注処理でエラーが発生しました');
    }
  }

  // CSVエクスポート
  async function exportCSV() {
    try {
      const orders = await window.aivicApi.list(9);
      if (!orders) return;

      const headers = ['発注ID', '店舗ID', '商品ID', '発注日', '発注数量', '発注金額', '発注ステータス', '発注理由'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...orders.map(order => [
          order.発注ID || '',
          order.店舗ID || '',
          order.商品ID || '',
          order.発注日 || '',
          order.発注数量 || '',
          order.発注金額 || '',
          order.発注ステータス || '',
          `"${(order.発注理由 || '').replace(/"/g, '""')}"`
        ].join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `発注データ_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error('CSVエクスポートエラー:', error);
    }
  }

  // イベントリスナー設定
  container.querySelector('#store-select').addEventListener('change', handleStoreChange);
  container.querySelector('#category-select').addEventListener('change', applyFilters);
  container.querySelector('#product-search').addEventListener('input', applyFilters);
  container.querySelector('#btn-search').addEventListener('click', handleSearch);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#category-select').value = '';
    container.querySelector('#date-start').value = '';
    container.querySelector('#date-end').value = '';
    container.querySelector('#product-search').value = '';
    applyFilters();
  });

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // モーダル関連
  container.querySelector('#modal-close').addEventListener('click', () => {
    container.querySelector('#order-modal').classList.add('hidden');
  });

  container.querySelector('#modal-cancel').addEventListener('click', () => {
    container.querySelector('#order-modal').classList.add('hidden');
  });

  container.querySelector('#modal-confirm').addEventListener('click', executeOrder);

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    // 発注量調整ボタン
    const adjustBtn = e.target.closest('.adjust-btn');
    if (adjustBtn) {
      const action = adjustBtn.dataset.action;
      const productId = adjustBtn.dataset.id;
      handleQuantityAdjust(productId, action);
      return;
    }

    // 発注ボタン
    const orderBtn = e.target.closest('.order-btn');
    if (orderBtn) {
      const productId = orderBtn.dataset.id;
      showOrderModal(productId);
      return;
    }
  });

  // 初期化
  initStoreOptions();
  renderProducts([], []);
}
